1	'use strict';
2	
3	const { createServer: buildServer } = require('node:http');
4	const { LockstepError, NotFoundError, ValidationError } = require('./errors');
5	const { Lockstep } = require('./service');
6	
7	/**
8	 * Minimal HTTP layer over the Lockstep service.
9	 *
10	 * Routing, request decoding, error mapping and the standard error envelope live
11	 * here; every product rule lives in `service.js`, `replay.js` and `sim.js`.
12	 */
13	const MAX_BODY_BYTES = 1_000_000;
14	
15	function readBody(request) {
16	  return new Promise((resolve, reject) => {
17	    const contentType = request.headers['content-type'];
18	    if (contentType === undefined || String(contentType).split(';')[0].trim().toLowerCase() !== 'application/json') {
19	      reject(new ValidationError('Content-Type must be application/json'));
20	      return;
21	    }
22	    const chunks = [];
23	    let size = 0;
24	    request.on('data', (chunk) => {
25	      size += chunk.length;
26	      if (size > MAX_BODY_BYTES) {
27	        reject(new ValidationError('request body must be at most 1000000 bytes'));
28	        request.destroy();
29	        return;
30	      }
31	      chunks.push(chunk);
32	    });
33	    request.on('end', () => {
34	      if (chunks.length === 0) {
35	        resolve(null);
36	        return;
37	      }
38	      try {
39	        resolve(JSON.parse(Buffer.concat(chunks).toString('utf8')));
40	      } catch {
41	        reject(new ValidationError('request body must be valid JSON'));
42	      }
43	    });
44	    request.on('error', reject);
45	  });
46	}
47	
48	function send(response, status, payload) {
49	  const body = Buffer.from(JSON.stringify(payload), 'utf8');
50	  response.writeHead(status, {
51	    'Content-Length': body.length,
52	    'Content-Type': 'application/json; charset=utf-8',
53	  });
54	  response.end(body);
55	}
56	
57	/** Read an optional JSON body: a request with no Content-Type carries no body. */
58	function readOptionalBody(request) {
59	  if (request.headers['content-type'] === undefined) {
60	    return Promise.resolve(null);
61	  }
62	  return readBody(request);
63	}
64	
65	function createHandler(service) {
66	  return async function handle(request, response) {
67	    try {
68	      const parts = new URL(request.url, 'http://localhost').pathname.split('/').filter((part) => part.length > 0);
69	      const { method } = request;
70	      const key = request.headers['idempotency-key'];
71	
72	      if (method === 'GET' && parts.length === 1 && parts[0] === 'health') {
73	        send(response, 200, { service: 'lockstepnet', status: 'ok' });
74	        return;
75	      }
76	      if (method === 'POST' && parts.length === 1 && parts[0] === 'matches') {
77	        send(response, 201, service.createMatch(await readBody(request), key));
78	        return;
79	      }
80	      if (parts.length >= 2 && parts[0] === 'matches') {
81	        const id = decodeURIComponent(parts[1]);
82	        if (method === 'GET' && parts.length === 2) {
83	          send(response, 200, service.getState(id));
84	          return;
85	        }
86	        if (method === 'GET' && parts.length === 3 && parts[2] === 'replay') {
87	          send(response, 200, service.replayFile(id));
88	          return;
89	        }
90	        if (method === 'POST' && parts.length === 3 && parts[2] === 'inputs') {
91	          send(response, 201, service.submitInputs(id, await readBody(request), key));
92	          return;
93	        }
94	        if (method === 'POST' && parts.length === 3 && parts[2] === 'tick') {
95	          send(response, 200, service.advance(id, await readBody(request), key));
96	          return;
97	        }
98	        if (method === 'POST' && parts.length === 3 && parts[2] === 'rollback') {
99	          const body = await readBody(request);
100	          if (!body || typeof body !== 'object' || Array.isArray(body) || !Number.isInteger(body.tick)) {
101	            throw new ValidationError('body must contain an integer tick');
102	          }
103	          for (const field of Object.keys(body)) {
104	            if (field !== 'tick') {
105	              throw new ValidationError(`body has unknown field ${field}`);
106	            }
107	          }
108	          send(response, 200, service.rollback(id, body.tick));
109	          return;
110	        }
111	        if (method === 'POST' && parts.length === 3 && parts[2] === 'verify') {
112	          send(response, 200, service.verify(await readBody(request)));
113	          return;
114	        }
115	        if (method === 'POST' && parts.length === 3 && parts[2] === 'sessions') {
116	          send(response, 201, service.createSession(id, await readBody(request), key));
117	          return;
118	        }
119	        if (method === 'POST' && parts.length === 3 && parts[2] === 'spectators') {
120	          send(response, 201, service.createSpectator(id, await readBody(request), key));
121	          return;
122	        }
123	        if (parts.length === 5 && parts[2] === 'sessions') {
124	          const sessionId = decodeURIComponent(parts[3]);
125	          const action = parts[4];
126	          if (method === 'POST' && action === 'inputs') {
127	            send(response, 201, service.submitSessionInputs(id, sessionId, await readBody(request), key));
128	            return;
129	          }
130	          if (method === 'POST' && action === 'disconnect') {
131	            send(response, 200, service.disconnectSession(id, sessionId, await readOptionalBody(request), key));
132	            return;
133	          }
134	          if (method === 'POST' && action === 'resume') {
135	            send(response, 200, service.resumeSession(id, sessionId, await readBody(request), key));
136	            return;
137	          }
138	        }
139	        if (parts.length === 5 && parts[2] === 'spectators') {
